## Handler

```ts
import { Pool } from "pg";
import { createHash, randomUUID } from "node:crypto";
import type { Request, Response, NextFunction } from "express";

const STALE_AFTER = "5 minutes"; // must exceed your slowest legitimate request
const RETRY_AFTER_SECONDS = 2;

class LostClaimError extends Error {}

const hashBody = (body: unknown) =>
  createHash("sha256").update(JSON.stringify(body ?? null)).digest("hex");

export function createOrderHandler(pool: Pool) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const key = req.header("Idempotency-Key");
    if (!key || key.length > 255) {
      return res.status(400).json({ error: "Idempotency-Key header required (max 255 chars)" });
    }

    // Validate BEFORE claiming, so a 400 is never stored and replayed.
    const problem = validateOrder(req.body);
    if (problem) return res.status(400).json({ error: problem });

    const userId = req.user.id; // from your auth middleware
    const requestHash = hashBody(req.body);
    const token = randomUUID();

    try {
      // 1. Atomically claim the key: insert it, or take over a stale
      //    in_progress row with the same payload. No row returned = not ours.
      const claim = await pool.query(
        `INSERT INTO idempotency_keys (user_id, key, request_hash, status, claim_token)
         VALUES ($1, $2, $3, 'in_progress', $4)
         ON CONFLICT (user_id, key) DO UPDATE
           SET claim_token = EXCLUDED.claim_token, locked_at = now()
           WHERE idempotency_keys.status = 'in_progress'
             AND idempotency_keys.request_hash = EXCLUDED.request_hash
             AND idempotency_keys.locked_at < now() - $5::interval
         RETURNING key`,
        [userId, key, requestHash, token, STALE_AFTER]
      );

      if (claim.rowCount === 0) {
        // 2. Someone else owns it. Decide what to tell the client.
        const { rows } = await pool.query(
          `SELECT request_hash, status, response_code, response_body
           FROM idempotency_keys WHERE user_id = $1 AND key = $2`,
          [userId, key]
        );
        const existing = rows[0];

        if (existing && existing.request_hash !== requestHash) {
          return res.status(422).json({ error: "Idempotency-Key was already used with a different request" });
        }
        if (existing?.status === "completed") {
          return res
            .status(existing.response_code)
            .set("Idempotent-Replayed", "true")
            .json(existing.response_body);
        }
        // in_progress and not stale (or the row was just cleaned up)
        return res
          .status(409)
          .set("Retry-After", String(RETRY_AFTER_SECONDS))
          .json({ error: "A request with this key is still in progress" });
      }

      // 3. We own the key. Create the order and mark the key completed in
      //    ONE transaction, so a crash leaves no order and a safely retryable row.
      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        const order = await insertOrder(client, userId, req.body); // your logic
        const responseBody = { order };

        const done = await client.query(
          `UPDATE idempotency_keys
           SET status = 'completed', response_code = 201, response_body = $3
           WHERE user_id = $1 AND key = $2
             AND status = 'in_progress' AND claim_token = $4`,
          [userId, key, JSON.stringify(responseBody), token]
        );
        // Zero rows means another request took over our row (we were too slow).
        if (done.rowCount === 0) throw new LostClaimError();

        await client.query("COMMIT");
        return res.status(201).json(responseBody);
      } catch (err) {
        await client.query("ROLLBACK");

        if (err instanceof LostClaimError) {
          return res.status(409).set("Retry-After", String(RETRY_AFTER_SECONDS))
            .json({ error: "Request superseded by a retry; please retry" });
        }
        // Release our claim so the client's retry can proceed immediately.
        await pool.query(
          `DELETE FROM idempotency_keys
           WHERE user_id = $1 AND key = $2 AND claim_token = $3 AND status = 'in_progress'`,
          [userId, key, token]
        ).catch(() => {}); // if this fails, the stale timeout still covers it
        throw err;
      } finally {
        client.release();
      }
    } catch (err) {
      next(err);
    }
  };
}
```

## Why it's built this way

- **The claim is a single statement.** Two concurrent requests with the same key can't both win, because the primary key plus `ON CONFLICT` decides it.
- **The order and the completion marker commit together.** If they were separate, a crash between them would create an order and leave the row `in_progress`, and the stale takeover would then create a duplicate. This is the main reason the order insert has to use the same transaction.
- **`claim_token` guards against slow-but-alive requests.** If request A stalls past 5 minutes and request B takes over, A's final `UPDATE` matches no rows, so A rolls back instead of creating a second order. The cost is that A's client gets a 409 and retries into B's result.
- **Failures are not cached.** Validation errors return before the claim. Unexpected errors delete the claim, so the retry runs fresh instead of replaying a 500.
- **Set `STALE_AFTER` above your slowest legitimate order request.** If it's shorter, you'll see takeovers (and 409s from the fencing) on requests that were merely slow.
- **`JSON.stringify` is key-order sensitive.** A client that serializes the same payload with different key order gets a 422. This is fine if one client library sends all requests. Otherwise, use a canonical JSON serializer in `hashBody`.
- **Any side effects outside the database** (payment capture, emails) need their own idempotency, such as passing the key through to the payment provider. The transaction only protects what's inside Postgres.

