I'm assuming Python, `prometheus_client`, and a hand-rolled breaker, since you haven't said which HTTP client or breaker library you use and I'd rather not guess. The HTTP call is injected as a `send` function and the breaker is a small class with `allow()` and `record()`, so you can swap in your client or a library like `pybreaker` without touching the retry logic. Separately, I haven't seen the bank's idempotency key retention window. The wrapper has an overall deadline, so check that deadline plus your reconciliation delay stays inside that window.

This reuses `make_idempotency_key` and the metrics from earlier.

```python
import random
import threading
import time
from collections import deque
from dataclasses import dataclass

RETRYABLE = {"timeout", "conn_error", "server_error", "rate_limited"}
BREAKER_FAILURES = RETRYABLE                       # declines and 4xx mean the bank is up
AMBIGUOUS = {"timeout", "conn_error", "server_error"}  # bank may have processed the charge


@dataclass
class Config:
    max_attempts: int = 3
    attempt_timeout: float = 3.0   # per HTTP attempt; keep close to your p99 when healthy
    deadline: float = 15.0         # total budget for the whole call, including backoff
    base_delay: float = 0.2
    max_delay: float = 2.0


@dataclass
class BankResult:
    outcome: str       # "success" or "declined"
    response: object
    attempts: int


class BankCallFailed(Exception):
    def __init__(self, result, last_outcome, attempts, unknown_outcome):
        super().__init__(f"bank call failed: {result} (last attempt: {last_outcome})")
        self.result = result                  # exhausted | breaker_open | deadline_exceeded | client_error
        self.last_outcome = last_outcome
        self.attempts = attempts
        self.unknown_outcome = unknown_outcome  # True => reconcile using the idempotency key


class CircuitBreaker:
    def __init__(self, window=20, min_calls=10, failure_ratio=0.5,
                 open_seconds=15.0, probes=3, on_transition=None,
                 clock=time.monotonic):
        self._results = deque(maxlen=window)   # True = success
        self._min_calls, self._ratio = min_calls, failure_ratio
        self._open_seconds, self._probes = open_seconds, probes
        self._on_transition = on_transition or (lambda old, new: None)
        self._clock = clock
        self._lock = threading.Lock()
        self.state = "closed"
        self._opened_at = 0.0
        self._in_flight = 0
        self._probe_ok = 0

    def _to(self, new):
        old, self.state = self.state, new
        if new == "open":
            self._opened_at = self._clock()
        if new in ("half_open", "closed"):
            self._in_flight = self._probe_ok = 0
        if new == "closed":
            self._results.clear()
        self._on_transition(old, new)

    def allow(self) -> bool:
        with self._lock:
            if self.state == "open":
                if self._clock() - self._opened_at < self._open_seconds:
                    return False
                self._to("half_open")
            if self.state == "half_open":
                if self._in_flight + self._probe_ok >= self._probes:
                    return False
                self._in_flight += 1
            return True

    def record(self, success: bool):
        with self._lock:
            if self.state == "half_open":
                self._in_flight = max(0, self._in_flight - 1)
                if not success:
                    self._to("open")
                else:
                    self._probe_ok += 1
                    if self._probe_ok >= self._probes:
                        self._to("closed")
            elif self.state == "closed":
                self._results.append(success)
                n = len(self._results)
                if n >= self._min_calls and (n - sum(self._results)) / n >= self._ratio:
                    self._to("open")
            # state == "open": late result from before the trip; ignore


def breaker_metrics_hook(old, new):
    for s in ("closed", "open", "half_open"):
        BREAKER_STATE.labels(s).set(1 if s == new else 0)
    BREAKER_TRANSITIONS.labels(old, new).inc()


def _retry_after(resp):
    try:
        return float(resp.headers.get("Retry-After", ""))
    except (ValueError, AttributeError):
        return 0.0


def _attempt(operation, send, key, timeout):
    """One HTTP attempt: returns (outcome, response). Replaces timed_attempt."""
    IN_FLIGHT.labels(operation).inc()
    start = time.monotonic()
    exc = resp = None
    try:
        resp = send(idempotency_key=key, timeout=timeout)
    except Exception as e:
        exc = e
    finally:
        outcome = classify(exc, resp)
        ATTEMPT_DURATION.labels(operation, outcome).observe(time.monotonic() - start)
        ATTEMPTS.labels(operation, outcome).inc()
        IN_FLIGHT.labels(operation).dec()
    return outcome, resp


def call_bank(send, payment, breaker, cfg=Config(), operation="charge"):
    """
    send(idempotency_key, timeout) -> response   (adapter around your HTTP client;
    must enforce `timeout` on connect and read, and raise on transport errors)
    """
    key = make_idempotency_key(payment.id, payment.generation)  # once, outside the loop
    start = time.monotonic()
    deadline = start + cfg.deadline
    attempts, last_outcome = 0, None

    def finish(result):
        CALLS.labels(operation, result).inc()
        CALL_DURATION.labels(operation, result).observe(time.monotonic() - start)
        if attempts:
            ATTEMPTS_PER_CALL.labels(operation).observe(attempts)

    def fail(result):
        unknown = last_outcome in AMBIGUOUS
        if unknown:
            UNKNOWN_OUTCOMES.labels(operation).inc()
        finish(result)
        raise BankCallFailed(result, last_outcome, attempts, unknown)

    for attempt in range(1, cfg.max_attempts + 1):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            fail("deadline_exceeded")
        if not breaker.allow():
            BREAKER_REJECTIONS.labels(operation).inc()
            fail("breaker_open")

        attempts = attempt
        outcome, resp = _attempt(operation, send, key, min(cfg.attempt_timeout, remaining))
        breaker.record(outcome not in BREAKER_FAILURES)
        last_outcome = outcome

        if outcome in ("success", "declined"):
            finish(outcome)
            return BankResult(outcome, resp, attempts)
        if outcome not in RETRYABLE:          # client_error: retrying won't help
            fail("client_error")
        if attempt == cfg.max_attempts:
            break

        # Full jitter, honouring Retry-After on 429
        delay = random.uniform(0, min(cfg.max_delay, cfg.base_delay * 2 ** (attempt - 1)))
        if outcome == "rate_limited":
            delay = max(delay, _retry_after(resp))
        if delay >= deadline - time.monotonic():
            fail("deadline_exceeded")
        RETRIES.labels(operation, outcome).inc()
        time.sleep(delay)

    fail("exhausted")
```

