    const { rows } = await client.query(
      'SELECT id, email, first_name FROM users WHERE lower(email) = $1 FOR UPDATE',
      [email]
    );
    if (rows.length === 0) {
      await client.query('ROLLBACK');
      return; // Unknown address: do nothing (see notes for the alternative).
    }
    user = rows[0];

    // Per-account throttle: silently skip if too many recent requests.
    const { rows: [{ count }] } = await client.query(
