const config = require('../config');
const logger = require('../logger');

const router = express.Router();

// Single source of truth, also passed to the email template.
const RESET_TOKEN_TTL_MINUTES = 30;
const MAX_TOKENS_PER_USER_PER_HOUR = 3;

const GENERIC_RESPONSE = {
  message:
    "If an account exists for that email, we've sent a link to reset the password.",
};

// Per-IP limit. Use a shared store (e.g., rate-limit-redis) if you run multiple instances.
const ipLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: { message: 'Too many requests. Please try again later.' },
});

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

router.post(
  '/password-reset/request',
  ipLimiter,
  express.json({ limit: '1kb' }),
  async (req, res) => {
    const raw = typeof req.body?.email === 'string' ? req.body.email : '';
    const email = raw.trim().toLowerCase();

    // Format errors reveal nothing about which accounts exist.
    if (email.length > 254 || !EMAIL_RE.test(email)) {
      return res.status(400).json({ message: 'Please enter a valid email address.' });
    }

    // Respond first so response time doesn't reveal whether the account exists.
    res.status(202).json(GENERIC_RESPONSE);

    try {
      await issueResetToken({
        email,
        ip: req.ip,
        userAgent: (req.get('user-agent') || '').slice(0, 255),
      });
    } catch (err) {
      // Never log the token or reset URL.
      logger.error({ err }, 'password reset issuance failed');
    }
  }
);

async function issueResetToken({ email, ip, userAgent }) {
  const client = await pool.connect();
  let token;
  let user;
  let requestedAt;

  try {
    await client.query('BEGIN');

    // Lock the user row so concurrent requests can't bypass the per-user cap.
    const { rows } = await client.query(
      `SELECT id, email, first_name
         FROM users
        WHERE lower(email) = $1
        FOR UPDATE`,
      [email]
    );
    if (rows.length === 0) {
      await client.query('ROLLBACK');
      return; // Unknown email: do nothing, the caller already responded.
    }
    user = rows[0];

    // Per-account cap, to stop email bombing of a victim.
    const { rows: recent } = await client.query(
      `SELECT count(*)::int AS n
         FROM password_reset_tokens
        WHERE user_id = $1
          AND created_at > now() - interval '1 hour'`,
      [user.id]
    );
    if (recent[0].n >= MAX_TOKENS_PER_USER_PER_HOUR) {
      await client.query('ROLLBACK');
      logger.warn({ userId: user.id }, 'password reset rate cap hit');
      return;
    }

    // Invalidate earlier outstanding tokens so only the newest link works.
    await client.query(
      `UPDATE password_reset_tokens
          SET used_at = now()
        WHERE user_id = $1 AND used_at IS NULL`,
      [user.id]
    );

    // 256-bit CSPRNG token. Only its SHA-256 is stored.
    token = crypto.randomBytes(32).toString('base64url');
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

    const { rows: inserted } = await client.query(
      `INSERT INTO password_reset_tokens
              (user_id, token_hash, expires_at, requested_ip, user_agent)
       VALUES ($1, $2, now() + make_interval(mins => $3), $4, $5)
       RETURNING created_at`,
      [user.id, tokenHash, RESET_TOKEN_TTL_MINUTES, ip, userAgent]
    );
    requestedAt = inserted[0].created_at;

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }

  // Send only after commit, so we never email a token that isn't stored.
  // Build the URL from config, never from the Host header (host-header poisoning).
  const resetUrl = `${config.appBaseUrl}/reset-password?token=${token}`;

  await sendPasswordResetEmail({
    to: user.email,
    firstName: user.first_name,
    resetUrl,
    expiryMinutes: RESET_TOKEN_TTL_MINUTES,
    requestedAt,
  });
}

module.exports = { router, RESET_TOKEN_TTL_MINUTES };
