        WHERE p.id = $1`,
      [id]
    );

    if (current.rowCount === 0) {
      return res.status(404).json({
        error: {
          code: "paragraph_deleted",
          message: "This paragraph no longer exists.",
        },
      });
    }

    const row = current.rows[0];
    return res.status(409).json({
      error: {
        code: "version_conflict",
        message:
          "This paragraph was changed by someone else since you started editing.",
      },
      conflict: {
        paragraph_id: id,
        your_base_version: client_version,
        current_version: row.version,
        current: {
          content: row.content,
          updated_at: row.updated_at,
          updated_by: row.user_id
            ? { id: row.user_id, name: row.user_name }
            : null,
        },
      },
    });
  } catch (err) {
    console.error("save paragraph failed", err);
    return res.status(500).json({
      error: { code: "internal_error", message: "Could not save." },
    });
  }
});
```

**Notes**

- **Schema assumptions:** this uses `updated_at` and `updated_by` columns, plus a `users` table. The migration I wrote only added `version`, so if those columns don't exist, add them or drop those fields from the handler and the 409 body.
- **Atomicity:** the version check lives in the `WHERE` clause of the `UPDATE`, so two simultaneous saves can't both succeed. Don't split it into a SELECT and then an UPDATE.
- **Resubmitting after a merge:** the client sends `current_version` from the 409 as the new `client_version`. If someone saves again in between, they get another 409, which is correct.
- **Other write paths:** imports, background jobs, and any other code that updates `paragraphs` must use the same `WHERE version = ...` pattern, or they'll bypass the check and reintroduce silent overwrites.
- **Retries:** if a client retries after a network timeout and the first attempt actually succeeded, the retry will get a 409 against its own write. The client can detect this by comparing `current.content` to what it sent and treating it as success.

