Here's the hook. It writes a local draft every 5 seconds when content has changed, and it accepts an optional `saveToServer` function so you can add server persistence without rewriting it.

```tsx
import { useCallback, useEffect, useRef, useState } from "react";
import { saveDraft, clearDraft } from "./drafts";
import type { SaveStatus } from "./SaveIndicator";

export interface UseAutosaveOptions {
  docId: string;
  content: string;
  /** Server revision the current content is based on (stored with the draft). */
  baseRevision?: string | number | null;
  intervalMs?: number;
  enabled?: boolean;
  /** Optional. If provided, each tick also persists to the server. */
  saveToServer?: (content: string) => Promise<void>;
}

export interface UseAutosaveResult {
  status: SaveStatus;
  savedAt: number | null;
  target: "local" | "server";
  /** Set when the last server save failed (even if the local draft succeeded). */
  serverError: unknown | null;
  /** Save immediately, e.g. on a "Save" button or before navigation. */
  flush: () => Promise<void>;
}

export function useAutosave({
  docId,
  content,
  baseRevision = null,
  intervalMs = 5000,
  enabled = true,
  saveToServer,
}: UseAutosaveOptions): UseAutosaveResult {
  const [status, setStatus] = useState<SaveStatus>("idle");
  const [savedAt, setSavedAt] = useState<number | null>(null);
  const [target, setTarget] = useState<"local" | "server">(
    saveToServer ? "server" : "local"
  );
  const [serverError, setServerError] = useState<unknown | null>(null);

  // Latest values, readable from the interval without resetting it.
  const contentRef = useRef(content);
  const baseRevisionRef = useRef(baseRevision);
  const saveToServerRef = useRef(saveToServer);
  contentRef.current = content;
  baseRevisionRef.current = baseRevision;
  saveToServerRef.current = saveToServer;

  // What has already been persisted, so unchanged content is never re-saved.
  const serverContentRef = useRef<string | null>(content); // known-persisted baseline
  const localContentRef = useRef<string | null>(null);     // last content written to draft
  const inFlightRef = useRef(false);
  const activeDocRef = useRef(docId);

  // Reset when switching documents.
  useEffect(() => {
    activeDocRef.current = docId;
    serverContentRef.current = contentRef.current;
    localContentRef.current = null;
    inFlightRef.current = false;
    setStatus("idle");
    setSavedAt(null);
    setServerError(null);
  }, [docId]);

  // Mark dirty as soon as content diverges from what's been persisted.
  useEffect(() => {
    if (
      !inFlightRef.current &&
      content !== serverContentRef.current &&
      content !== localContentRef.current
    ) {
      setStatus("dirty");
    }
  }, [content]);

  const save = useCallback(async () => {
    if (inFlightRef.current) return;

    const text = contentRef.current;
    const server = saveToServerRef.current;

    const needsServer = !!server && text !== serverContentRef.current;
    const needsLocal =
      text !== localContentRef.current && text !== serverContentRef.current;
    if (!needsLocal && !needsServer) return;

    // 1. Local draft first: it's synchronous and protects against crashes
    //    or tab closes while the network request is in flight.
    let localOk = !needsLocal;
    if (needsLocal) {
      localOk = saveDraft(docId, text, baseRevisionRef.current);
      if (localOk) localContentRef.current = text;
    }

    if (!needsServer || !server) {
      setTarget("local");
      setStatus(localOk ? "saved" : "error");
      if (localOk) setSavedAt(Date.now());
      return;
    }

    // 2. Server save (optional).
    inFlightRef.current = true;
    setStatus("saving");
    try {
      await server(text);
      if (activeDocRef.current !== docId) return; // user switched documents

      serverContentRef.current = text;
      setServerError(null);
      setTarget("server");
      setSavedAt(Date.now());

      if (contentRef.current === text) {
        clearDraft(docId); // safe: the server has exactly what's on screen
        localContentRef.current = null;
        setStatus("saved");
      } else {
        setStatus("dirty"); // user kept typing; the next tick handles it
      }
    } catch (err) {
      if (activeDocRef.current !== docId) return;
      setServerError(err);
      // Draft is kept. Show "saved locally" if that worked, otherwise error.
      setTarget(localOk ? "local" : "server");
      setStatus(localOk ? "saved" : "error");
      if (localOk) setSavedAt(Date.now());
    } finally {
      inFlightRef.current = false;
    }
  }, [docId]);

  // The 5-second loop.
  useEffect(() => {
    if (!enabled) return;
    const id = setInterval(() => void save(), intervalMs);
    return () => clearInterval(id);
  }, [enabled, intervalMs, save]);

  // Flush the local draft when the tab is hidden or closing.
  // localStorage is synchronous, so this completes before unload.
  useEffect(() => {
    if (!enabled) return;

    const flushLocal = () => {
      const text = contentRef.current;
      if (
        text !== serverContentRef.current &&
        text !== localContentRef.current &&
        saveDraft(docId, text, baseRevisionRef.current)
      ) {
        localContentRef.current = text;
      }
    };
    const onVisibility = () => {
      if (document.visibilityState === "hidden") flushLocal();
    };

    window.addEventListener("pagehide", flushLocal);
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      flushLocal(); // also on unmount / doc switch
      window.removeEventListener("pagehide", flushLocal);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [enabled, docId]);

  return { status, savedAt, target, serverError, flush: save };
}
```

Usage:

```tsx
function Editor({ docId, initialContent, revision }: Props) {
  const [content, setContent] = useState(initialContent);

  const { status, savedAt, target } = useAutosave({
    docId,
    content,
    baseRevision: revision,
    // saveToServer: (text) => api.saveDocument(docId, text, revision),
  });

  return (
    <>
      <SaveIndicator status={status} savedAt={savedAt} target={target} />
      <textarea value={content} onChange={(e) => setContent(e.target.value)} />
    </>
  );
}
```

Design notes:

- **Refs for the interval:** The timer reads the latest content through refs, so typing doesn't tear down and recreate the interval. Otherwise continuous typing could keep resetting the 5s countdown and nothing would ever save.
- **Local write before server write:** The draft is written first and cleared only after the server confirms, and only if the screen content still matches what was sent. If the user typed during the request, the draft stays and the next tick covers the new text.
- **Server failure with a good local draft:** The indicator shows "Draft saved locally" rather than "Saved", and `serverError` is exposed so you can show a stronger warning or a retry. The next tick retries automatically.
- **No overlapping requests:** `inFlightRef` stops a slow server response from stacking up concurrent saves every 5 seconds.
- **Unload flush:** `pagehide` and `visibilitychange` catch the cases the 5s timer would miss, like closing the tab 3 seconds after the last tick.

Two limitations to be aware of:

1. **A local-only draft only covers crashes, accidental closes, and refreshes.** If some of the lost edits come from failed server saves, conflicts, or switching devices, the draft won't help until `saveToServer` is wired in. It's worth checking which cause your users are hitting.
2. **Two tabs on the same document share one draft key** and will overwrite each other. If that's plausible for your users, I can add a `storage` event listener or a tab id to the draft.

The next piece is the restore-on-open flow: on load, call `loadDraft`, compare `baseRevision` with the server's current revision, and either restore silently or prompt on conflict. Want me to write that?

