```kotlin
import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.net.Uri
import android.view.View
import android.widget.ImageView
import androidx.core.view.doOnLayout
import androidx.exifinterface.media.ExifInterface
import kotlinx.coroutines.*
import java.util.WeakHashMap
import kotlin.coroutines.coroutineContext
import kotlin.coroutines.resume

class GalleryImageLoader(
    context: Context,
    private val cache: BitmapMemoryCache,
    maxParallelDecodes: Int = 2,
    private val config: Bitmap.Config = Bitmap.Config.RGB_565
) {
    private val resolver = context.applicationContext.contentResolver

    // Caps concurrent decodes so fast scrolling can't pile up in-flight bitmaps.
    private val decodeDispatcher = Dispatchers.IO.limitedParallelism(maxParallelDecodes)

    // Main thread only.
    private val jobs = WeakHashMap<ImageView, Job>()

    /** Loads into an ImageView. [scope] must run on Dispatchers.Main (e.g. lifecycleScope). */
    fun loadInto(
        view: ImageView,
        uri: Uri,
        scope: CoroutineScope,
        targetWidth: Int = 0,   // pass the grid cell size if you know it
        targetHeight: Int = 0
    ) {
        cancel(view)
        view.setImageDrawable(null) // don't show the previous item's image in a recycled view

        jobs[view] = scope.launch {
            val (w, h) = if (targetWidth > 0 && targetHeight > 0) {
                targetWidth to targetHeight
            } else {
                view.awaitSize()
            }
            if (w <= 0 || h <= 0) return@launch // never decode at full size by accident

            val bitmap = load(uri, w, h)
            if (bitmap != null) view.setImageBitmap(bitmap)
        }
    }

    fun cancel(view: ImageView) {
        jobs.remove(view)?.cancel()
    }

    suspend fun load(uri: Uri, reqWidth: Int, reqHeight: Int): Bitmap? {
        val key = BitmapMemoryCache.key(uri.toString(), reqWidth, reqHeight)
        cache.get(key)?.let { return it }

        return withContext(decodeDispatcher) {
            // Re-check: another request may have filled the cache while we waited for a slot.
            cache.get(key)?.let { return@withContext it }
            decode(uri, reqWidth, reqHeight)?.also { cache.put(key, it) }
        }
    }

    private suspend fun decode(uri: Uri, reqWidth: Int, reqHeight: Int): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

        val orientation = readOrientation(uri)
        val swap = orientation in DIMENSION_SWAPPING
        val srcW = if (swap) bounds.outHeight else bounds.outWidth
        val srcH = if (swap) bounds.outWidth else bounds.outHeight

        var sampleSize = calculateInSampleSize(srcW, srcH, reqWidth, reqHeight)

        // One retry at half the resolution if we hit OOM.
        repeat(2) {
            coroutineContext.ensureActive() // skip the decode if the view was recycled
            try {
                val options = BitmapFactory.Options().apply {
                    inSampleSize = sampleSize
                    inPreferredConfig = config
                }
                val bmp = resolver.openInputStream(uri)?.use {
                    BitmapFactory.decodeStream(it, null, options)
                } ?: return null
                return applyOrientation(bmp, orientation)
            } catch (e: OutOfMemoryError) {
                cache.evictAll()
                sampleSize *= 2
            }
        }
        return null
    }

    private fun readOrientation(uri: Uri): Int = try {
        resolver.openInputStream(uri)?.use {
            ExifInterface(it).getAttributeInt(
                ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL
            )
        } ?: ExifInterface.ORIENTATION_NORMAL
    } catch (e: Exception) {
        ExifInterface.ORIENTATION_NORMAL
    }

    private fun applyOrientation(bmp: Bitmap, orientation: Int): Bitmap {
        val m = Matrix()
        when (orientation) {
            ExifInterface.ORIENTATION_ROTATE_90 -> m.postRotate(90f)
            ExifInterface.ORIENTATION_ROTATE_180 -> m.postRotate(180f)
            ExifInterface.ORIENTATION_ROTATE_270 -> m.postRotate(270f)
            ExifInterface.ORIENTATION_FLIP_HORIZONTAL -> m.postScale(-1f, 1f)
            ExifInterface.ORIENTATION_FLIP_VERTICAL -> m.postScale(1f, -1f)
            ExifInterface.ORIENTATION_TRANSPOSE -> { m.postRotate(90f); m.postScale(-1f, 1f) }
            ExifInterface.ORIENTATION_TRANSVERSE -> { m.postRotate(270f); m.postScale(-1f, 1f) }
            else -> return bmp
        }
        val out = Bitmap.createBitmap(bmp, 0, 0, bmp.width, bmp.height, m, true)
        if (out !== bmp) bmp.recycle() // safe: bmp was never shared or cached
        return out
    }

    private suspend fun View.awaitSize(): Pair<Int, Int> =
        suspendCancellableCoroutine { cont ->
            doOnLayout { if (cont.isActive) cont.resume(width to height) }
        }

    private companion object {
        val DIMENSION_SWAPPING = setOf(
            ExifInterface.ORIENTATION_ROTATE_90,
            ExifInterface.ORIENTATION_ROTATE_270,
            ExifInterface.ORIENTATION_TRANSPOSE,
            ExifInterface.ORIENTATION_TRANSVERSE
        )
    }
}
