One thing the question assumes: that a hand-rolled loader is the right call. Glide and Coil already handle downsampling, bounded caches, bitmap pooling, in-flight deduplication, and lifecycle-aware cancellation, and those are the parts that are easy to get subtly wrong. Since you're fixing a crash spike, a custom loader is also a new source of risk. If you haven't compared them, a Coil or Glide swap on this one screen is a small change, and it's worth trying before you ship custom code. If you've decided to go custom, here is a loader that covers the concerns that matter.

```kotlin
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import androidx.exifinterface.media.ExifInterface
import kotlinx.coroutines.*

class ImageLoader(
    private val cache: BitmapMemoryCache,
    private val scope: CoroutineScope,          // must be Main-confined, e.g. lifecycleScope
    maxParallelDecodes: Int = 2
) {
    private val decodeDispatcher = Dispatchers.IO.limitedParallelism(maxParallelDecodes)

    private class InFlight {
        lateinit var deferred: Deferred<Bitmap?>
        var waiters = 0
    }

    // Only touched on the main thread.
    private val inFlight = HashMap<String, InFlight>()

    /** Call from the main thread. Cancelling the caller releases its interest in the decode. */
    suspend fun load(path: String, reqW: Int, reqH: Int): Bitmap? {
        val key = BitmapMemoryCache.key(path, reqW, reqH)
        cache.get(key)?.let { return it }

        var entry = inFlight[key]
        if (entry == null || entry.deferred.isCancelled) {
            val e = InFlight()
            e.deferred = scope.async(Dispatchers.Main.immediate) {
                try {
                    val bmp = withContext(decodeDispatcher) { decodeWithRetry(path, reqW, reqH) }
                    if (bmp != null) cache.put(key, bmp)
                    bmp
                } finally {
                    inFlight.remove(key, e)
                }
            }
            inFlight[key] = e
            entry = e
        }

        entry.waiters++
        try {
            return entry.deferred.await()
        } finally {
            // Last waiter gone (e.g. view recycled): cancel the decode.
            if (--entry.waiters == 0 && entry.deferred.isActive) entry.deferred.cancel()
        }
    }

    private suspend fun decodeWithRetry(path: String, w: Int, h: Int): Bitmap? =
        try {
            decode(path, w, h)
        } catch (e: OutOfMemoryError) {
            cache.evictAll()                    // free what we can, try once more
            try { decode(path, w, h) } catch (e: OutOfMemoryError) { null }
        }

    private suspend fun decode(path: String, reqW: Int, reqH: Int): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(path, bounds)
        currentCoroutineContext().ensureActive()  // BitmapFactory can't be interrupted mid-decode

        val orientation = try {
            ExifInterface(path).getAttributeInt(
                ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL
            )
        } catch (e: Exception) { ExifInterface.ORIENTATION_NORMAL }

        val degrees = when (orientation) {
            ExifInterface.ORIENTATION_ROTATE_90 -> 90f
            ExifInterface.ORIENTATION_ROTATE_180 -> 180f
            ExifInterface.ORIENTATION_ROTATE_270 -> 270f
            else -> 0f
        }
        val swap = degrees == 90f || degrees == 270f
        val srcW = if (swap) bounds.outHeight else bounds.outWidth
        val srcH = if (swap) bounds.outWidth else bounds.outHeight

        val opts = BitmapFactory.Options().apply {
            inSampleSize = calculateInSampleSize(srcW, srcH, reqW, reqH)
            inPreferredConfig = Bitmap.Config.RGB_565
        }
        val decoded = BitmapFactory.decodeFile(path, opts) ?: return null
        currentCoroutineContext().ensureActive()

        if (degrees == 0f) return decoded
        val rotated = Bitmap.createBitmap(
            decoded, 0, 0, decoded.width, decoded.height,
            Matrix().apply { postRotate(degrees) }, true
        )
        if (rotated !== decoded) decoded.recycle() // safe: never cached or shown
        return rotated
    }
}
